--
-- Name: team_targets(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.team_targets(p_rule uuid, p_level integer) RETURNS uuid[]
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE(array_agg(p.user_id ORDER BY p.sort_order, u.name, p.user_id), '{}'::uuid[])
      FROM routing_rule_people p
      JOIN users u ON u.id = p.user_id
     WHERE p.rule_id = p_rule
       AND p.level = p_level
       AND cardinality(public.route_targets(p.org_id, p.user_id, NULL, NULL)) > 0;
$$;


ALTER FUNCTION public.team_targets(p_rule uuid, p_level integer) OWNER TO postgres;

